1	// The torch op layer: validate the tensor, take the plan and the window from the group, then
2	// barrier, transfer, barrier, copy out.
3	//
4	// The group owns everything that survives a call -- windows, plans, staging buffers -- so the
5	// Python side is a constructor and two forwards.
6	#include <ATen/cuda/CUDAContext.h>
7	#include <c10/cuda/CUDAGuard.h>
8	#include <cuda_runtime.h>
9	#include <optional>
10	#include <torch/csrc/autograd/custom_function.h>
11	#include <torch/extension.h>
12	#include <torch/library.h>
13	
14	#include <map>
15	#include <string>
16	#include <tuple>
